-- Bengali training posters for lessons 9.1–9.10 (bn) — clean 1.10-style testing cards
-- Lesson 9.1
UPDATE training_chapters
SET
  content = '{"level_id":"9.1","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"ট্রান্সফরমার টেস্টিং (পার্ট ১): মৌলিক পরীক্ষা","mission_briefing":"সাবস্টেশনের ''অপারেশন থিয়েটারে'' স্বাগতম! আজকের রোগী হলো আমাদের পাওয়ার গ্রিডের হৃদপিণ্ড—''ট্রান্সফরমার''। বাইরে থেকে দেখে একে শক্তপোক্ত মনে হলেও, এর ভেতরে হাজারও সেনসিটিভ অংশ আছে। লাইন চার্জ করার আগে আমাদের নিশ্চিত হতে হবে যে এর ভেতরের ইনসুলেশন এবং ওয়াইন্ডিং সুস্থ আছে। একজন ডাক্তার যেমন স্টেথিসকোপ দিয়ে বুক পরীক্ষা করেন, আজ আমরা ''মেগার'' (Megger) এবং ''ওহম মিটার'' দিয়ে ট্রান্সফরমারের চেক-আপ করব। প্রস্তুত? চলুন শুরু করি।","sections":[{"title":"মৌলিক পরীক্ষার সরঞ্জাম ও পদ্ধতি","image_name":"/images/loader/xfrm91_megger.webp","points":[{"item_name":"১. ইনসুলেশন রেজিস্ট্যান্স (IR) টেস্ট বা ''মেগার'' টেস্ট","image_name":"/images/loader/xfrm91_megger.webp","specifications":"সাধারণত ৫০০০ ভোল্ট (5kV) বা ২৫০০ ভোল্ট (2.5kV) এর মোটোরাইজড বা হ্যান্ড-ড্রিভেন মেগার ব্যবহার করা হয়। টেস্টের সময় ট্রান্সফরমারের বডি ভালো করে আর্থ করা থাকতে হবে।","importance":"এটি ট্রান্সফরমারের ''ইমিউনিটি টেস্ট''। কারেন্ট কি সঠিক পথে যাচ্ছে, নাকি ইনসুলেশন ভেদ করে বডিতে লিক করছে? এই টেস্ট আমাদের সেটা জানায়। রিডিং যত বেশি (Mega Ohm বা Giga Ohm), ট্রান্সফরমার তত সুস্থ।","daily_check":"টেস্টের আগে বুশিংগুলো (Bushings) পরিষ্কার শুকনো কাপড় দিয়ে মুছে নিন। ধুলোবালি থাকলে রিডিং ভুল আসতে পারে।","image_caption":"মেগার · ইনসুলেশন IR"},{"item_name":"২. মেগার সংযোগের নিয়ম (Connection Logic)","image_name":"/images/loader/xfrm91_connect.webp","specifications":"তিনটি ধাপে এই টেস্ট হয়:\nক) HV (High Voltage) সাইড বনাম আর্থ (Earth)\nখ) LV (Low Voltage) সাইড বনাম আর্থ (Earth)\nগ) HV সাইড বনাম LV সাইড","importance":"এই তিনটি ধাপ নিশ্চিত করে যে, হাই ভোল্টেজ কয়েল, লো ভোল্টেজ কয়েল এবং ট্রান্সফরমারের বডি—এরা একে অপরের সাথে শর্ট হয়ে নেই।","daily_check":"কানেকশন টাইট আছে কিনা দেখুন। যখন HV টেস্ট করবেন, LV সাইডকে শর্ট করে আর্থ করে রাখা ভালো (Guard Terminal ব্যবহার করলে আরও ভালো)।","image_caption":"HV–E · LV–E · HV–LV"},{"item_name":"৩. ওয়াইন্ডিং রেজিস্ট্যান্স টেস্ট (Winding Resistance)","image_name":"/images/loader/xfrm91_winding.webp","specifications":"মাইক্রো-ওহম মিটার বা কেলভিন ব্রিজ ব্যবহার করে মাপা হয়। সাধারণ মাল্টিমিটার দিয়ে এই সূক্ষ্ম রেজিস্ট্যান্স মাপা সম্ভব নয়। ডিসি (DC) কারেন্ট ইনজেক্ট করে ভোল্টেজ ড্রপ মাপা হয়।","importance":"এটি ট্রান্সফরমারের ভেতরের তারের কন্টিনিউটি চেক করে। যদি কোথাও তার ছিঁড়ে যায় বা লুজ কানেকশন থাকে, তবে রেজিস্ট্যান্স অনেক বেশি দেখাবে। তিন ফেজের (R, Y, B) রিডিং প্রায় সমান হওয়া উচিত।","daily_check":"টেস্টের আগে ট্যাপ চেঞ্জার (Tap Changer) ফিক্সড পজিশনে আছে কিনা দেখে নিন। প্রতিটি ট্যাপ পজিশনে এই টেস্ট করা জরুরি।","image_caption":"ওয়াইন্ডিং · মাইক্রো-ওহম"},{"item_name":"৪. ম্যাগনেটিক ব্যালেন্স টেস্ট (প্রাথমিক ধারণা)","image_name":"/images/loader/xfrm91_balance.webp","specifications":"লো ভোল্টেজ (২৩০ ভোল্ট) এসসি সাপ্লাই দিয়ে এটি চেক করা হয়। এক ফেজে ভোল্টেজ দিলে বাকি দুই ফেজে কত ভোল্টেজ পাওয়া যাচ্ছে তা দেখা হয়।","importance":"এটি ট্রান্সফরমারের কোরের (Core) স্বাস্থ্য এবং ফ্লাক্স পাথ ঠিক আছে কিনা তা দ্রুত বুঝতে সাহায্য করে।","daily_check":"নিউট্রাল পয়েন্ট যেন আর্থ করা না থাকে, তা নিশ্চিত করুন।","image_caption":"ম্যাগনেটিক ব্যালেন্স · কোর"}],"image_caption":"মেগার · ইনসুলেশন IR"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. ডিসচার্জ রড ব্যবহার বাধ্যতামূলক: মেগার টেস্টের পর ট্রান্সফরমার চার্জ ধরে রাখে (Capacitor এর মতো)। হাত দেওয়ার আগে অবশ্যই ডিসচার্জ রড দিয়ে ওয়াইন্ডিং আর্থ করে ডিসচার্জ করুন। এটা না করলে জান যাওয়ার ঝুঁকি থাকে!","২. তাপমাত্রা ফ্যাক্টর: ইনসুলেশন রেজিস্ট্যান্স তাপমাত্রার সাথে বদলায়। রিডিং নেওয়ার সময় তেলের তাপমাত্রা (OTI) নোট করে রাখুন।","৩. ৬০ সেকেন্ডের নিয়ম: মেগার অন করার সাথে সাথে রিডিং নেবেন না। অন্তত ১ মিনিট অপেক্ষা করুন, যাতে রিডিং স্থির (Stable) হয়।","৪. লুজ কানেকশন শত্রু: ওয়াইন্ডিং রেজিস্ট্যান্স মাপার সময় ক্ল্যাম্পগুলো খুব শক্ত করে লাগান, নাহলে ভুল রিপোর্ট আসবে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"মেগার টেস্টে ''0'' (শূন্য) রিডিং মানে কন্টিনিউটি খুব ভালো।","reality":"ভয়ঙ্কর ভুল! মেগার টেস্টে ''0'' মানে হলো ইনসুলেশন ফেল করেছে বা ''ডেড শর্ট সার্কিট'' হয়ে গেছে। মেগারের রিডিং সবসময় ''ইনফিনিটি'' বা অনেক উচ্চ মানের (High Value) হওয়া উচিত।","verdict":"শূন্য মানেই বিপদ!"},{"myth":"পুরানো ট্রান্সফরমারের রেজিস্ট্যান্স নতুন ট্রান্সফরমারের মতোই হবে।","reality":"না। সময়ের সাথে সাথে কানেকশন এবং কপার বা অ্যালুমিনিয়ামের গুনাগুন কিছুটা বদলায়। তবে তিন ফেজের মধ্যে ভারসাম্য (Balance) থাকাটা জরুরি।"}],"image_name":"/images/loader/xfrm91_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ট্রান্সফরমার"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"PI ভ্যালু (Polarization Index)","content":"শুধু ১ মিনিটের মেগার ভ্যালু যথেষ্ট নয়। আমরা ১০ মিনিটের ভ্যালুকে ১ মিনিটের ভ্যালু দিয়ে ভাগ করে PI বের করি। যদি PI ভ্যালু ১.৫ বা ২-এর বেশি হয়, তবে বুঝবেন ইনসুলেশন খুব ভালো অবস্থায় আছে। ১-এর কম মানে ইনসুলেশন আর্দ্রতা বা ময়লায় আক্রান্ত।"},{"title":"কেন ডিসি (DC) কারেন্ট?","content":"ওয়াইন্ডিং রেজিস্ট্যান্স মাপার সময় আমরা ডিসি কারেন্ট ব্যবহার করি কারণ এসি (AC) দিলে ইনডাক্টেন্সের (Inductance) কারণে সঠিক রেজিস্ট্যান্স মাপা যাবে না। ডিসি কারেন্ট ইনডাক্টেন্সের প্রভাব দূর করে শুধু পিওর রেজিস্ট্যান্স দেখায়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.1' AND language = 'bn';

-- Lesson 9.2
UPDATE training_chapters
SET
  content = '{"level_id":"9.2","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"ট্রান্সফরমার টেস্টিং (পার্ট ২): তেল পরীক্ষা","mission_briefing":"শরীরের রক্ত যেমন অক্সিজেন বহন করে এবং শরীর ঠান্ডা রাখে, ট্রান্সফরমারের তেলও (Transformer Oil) ঠিক তাই করে—এটি ইনসুলেশন দেয় এবং কয়েলে তৈরি হওয়া তাপ কমিয়ে রাখে। কিন্তু এই তেলে যদি সামান্য জল বা ধুলো মিশে যায়, তবে তা ট্রান্সফরমারের জন্য ''বিষ'' হয়ে দাঁড়ায়। আজকের মিশনে আমরা শিখব কীভাবে এই তেলের স্যাম্পল নিতে হয় এবং ল্যাবে না পাঠিয়েও কীভাবে এর শক্তি বা ''BDV'' পরীক্ষা করতে হয়। গ্লাভস পরে নিন, আমরা লিকুইড গোল্ড (Liquid Gold) নিয়ে কাজ করব!","sections":[{"title":"তেলের স্যাম্পল কালেকশন ও বিডিভি (BDV) টেস্ট","image_name":"/images/loader/oil92_sample.webp","points":[{"item_name":"১. স্যাম্পল কালেকশন: প্রথম ধাপেই সতর্কতা","image_name":"/images/loader/oil92_sample.webp","specifications":"কাঁচের বা স্টেইনলেস স্টিলের পরিষ্কার বোতল ব্যবহার করতে হবে। প্লাস্টিক বোতল চলবে না।","importance":"ভুল পদ্ধতিতে স্যাম্পল নিলে ল্যাবের রিপোর্ট ভুল আসবে। মনে রাখবেন, তেল সবসময় ট্রান্সফরমারের নিচের ভালভ (Bottom Valve) থেকে নিতে হয়। কারণ জল এবং ভারী গাদ (Sludge) তেলের নিচে জমা হয়। ওপর থেকে তেল নিলে আপনি আসল সমস্যা ধরতে পারবেন না।","daily_check":"বোতলটি যেন সম্পূর্ণ শুকনো থাকে। স্যাম্পল নেওয়ার আগে ১-২ লিটার তেল ফেলে দিয়ে লাইন ক্লিয়ার করে তারপর বোতলে তেল ভরুন।","image_caption":"তেল স্যাম্পল · নিচের ভালভ"},{"item_name":"২. তেলের ভিজ্যুয়াল চেক: রঙ কী বলে?","image_name":"/images/loader/oil92_color.webp","specifications":"পরিষ্কার কাঁচের জারে তেল নিয়ে আলোর সামনে ধরুন।","importance":"নতুন তেল একেবারে স্বচ্ছ বা হালকা হলুদ (Pale Yellow) হয়। যদি তেলের রঙ গাঢ় খয়েরি বা কালো হয়, তবে বুঝবেন তেল পুড়ে গেছে বা কার্বন জমেছে। ঘোলাটে (Cloudy) তেল মানে তাতে জল বা ময়েশ্চার মিশে আছে।","daily_check":"তেলের মধ্যে কোনো ভাসমান কণা (Suspended Particles) আছে কিনা দেখুন।","image_caption":"রঙ · স্বচ্ছ · ঘোলা"},{"item_name":"৩. বিডিভি (BDV) টেস্ট: শক্তির পরীক্ষা","image_name":"/images/loader/oil92_bdv.webp","specifications":"BDV মানে Breakdown Voltage। এই টেস্টের জন্য একটি ''অয়েল টেস্টিং কিট'' ব্যবহার করা হয়। এতে একটি বাটির (Pot) মধ্যে দুটো ইলেকট্রোড থাকে, যাদের মাঝখানের গ্যাপ সাধারণত ২.৫ মিমি (2.5mm) রাখা হয়।","importance":"আমরা দেখব দুই ইলেকট্রোডের মাঝে কত ভোল্টেজ দিলে তেলের ইনসুলেশন ভেঙে স্পার্ক (Spark) করে। ভোল্টেজ যত বেশি লাগবে, তেল তত ভালো। সাধারণত ৩০ কেভি (30kV) এর ওপরে রিডিং ভালো বলে গণ্য হয়।","daily_check":"টেস্ট কিটের বাটিটি খুব ভালো করে পরিষ্কার করুন। ইলেকট্রোডের গ্যাপ গেজ (Gauge) দিয়ে মেপে সেট করুন।","image_caption":"BDV · ২.৫ মিমি · ≥৩০ kV"},{"item_name":"৪. ক্র্যাকল টেস্ট (Crackle Test): দেশি পদ্ধতি","image_name":"/images/loader/oil92_crackle.webp","specifications":"মাঠে বসে দ্রুত জল পরীক্ষা করার পদ্ধতি। একটি টেস্ট টিউবে তেল নিয়ে গরম করা হয়, অথবা গরম রড তেলে ডোবানো হয়।","importance":"যদি তেল গরম করার সময় ''চড়চড়'' শব্দ (Cracking sound) হয়, তার মানে তেলে জল আছে। আর যদি নিঃশব্দে ধোঁয়া বের হয়, তবে তেল শুকনো (Dry) আছে।","daily_check":"এটি খুব সতর্কতার সাথে করতে হবে যেন আগুন না লাগে।","image_caption":"ক্র্যাকল · জল শনাক্ত"}],"image_caption":"তেল স্যাম্পল · নিচের ভালভ"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. বুদবুদ বা বাবলস (Bubbles): BDV কিটের বাটিতে তেল ঢালার পর সাথে সাথে টেস্ট শুরু করবেন না। অন্তত ১০ মিনিট অপেক্ষা করুন যাতে বাতাসের বুদবুদগুলো বেরিয়ে যায়। বুদবুদ থাকলে কম ভোল্টেজে স্পার্ক হবে এবং রিডিং ভুল আসবে।","২. গড় মান (Average): একবার টেস্ট করেই সিদ্ধান্ত নেবেন না। একই তেলে পরপর ৬ বার স্পার্ক করিয়ে ৬টি রিডিং নিন এবং তাদের গড় (Average) বের করুন। ওটাই আসল BDV ভ্যালু।","৩. বৃষ্টির দিনে না: বর্ষাকালে বা বাতাসে আর্দ্রতা বেশি থাকলে বাইরে তেলের স্যাম্পল নেওয়া বা টেস্ট করা উচিত নয়। বাতাস থেকে ময়েশ্চার তেলে ঢুকে যেতে পারে।","৪. হাতের স্পর্শ নিষেধ: ইলেকট্রোড বা স্যাম্পল বোতলের ভেতর আঙুল দেবেন না। আপনার হাতের ঘাম তেলের রেজাল্ট খারাপ করে দেবে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"তেল দেখতে পরিষ্কার মানেই তেল ভালো।","reality":"ভুল ধারণা। তেল দেখতে স্বচ্ছ হলেও তাতে ''ডিসলভড ময়েশ্চার'' (মিশে থাকা জল) বা অ্যাসিড থাকতে পারে যা খালি চোখে দেখা যায় না। ল্যাব টেস্ট বা BDV টেস্ট ছাড়া নিশ্চিত হওয়া যায় না।","verdict":"দর্শনধারী হলেই গুণবিচারী নয়!"},{"myth":"BDV টেস্টে একবার স্পার্ক করলেই তেল বাতিল।","reality":"না। তেল কার্বনাইজড হয়ে গেলে ফিল্টার মেশিনে (Centrifuge) ফিল্টার করে বা হিট দিয়ে আবার ব্যবহারযোগ্য করা যায়। তবে যদি বারবার খুব কম ভোল্টেজে স্পার্ক করে, তখন তেল বদলাতে হতে পারে।"}],"image_name":"/images/loader/oil92_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · তেল"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"PPM (Parts Per Million)","content":"BDV টেস্ট শুধুমাত্র ভোল্টেজ সহ্য ক্ষমতা মাপে। কিন্তু তেলে ঠিক কতটুকু জল আছে তা মাপতে ল্যাবে ''কার্ল ফিশার টাইটেশন'' (Karl Fischer) পদ্ধতি ব্যবহার করা হয়। হাই ভোল্টেজ ট্রান্সফরমারের জন্য ১০-১৫ PPM এর বেশি জল থাকা বিপজ্জনক।"},{"title":"DGA (Dissolved Gas Analysis)","content":"মানুষের ডিএনএ টেস্টের মতো ট্রান্সফরমারের সবচেয়ে অ্যাডভান্সড টেস্ট হলো DGA। ট্রান্সফরমারের ভেতরে কোনো ফল্ট হলে তেলে হাইড্রোজেন, অ্যাসিটিলিন বা মিথেন গ্যাস তৈরি হয়। তেলের স্যাম্পল থেকে এই গ্যাস বিশ্লেষণ করে বলা সম্ভব ট্রান্সফরমারের ভেতরে ঠিক কী সমস্যা হচ্ছে (আর্কিং, হিটিং নাকি ডিসচার্জ)।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.2' AND language = 'bn';

