UPDATE training_chapters
SET
  content = '{"level_id":"9.4","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"কেবিল টেস্টিং: লুকানো নেটওয়ার্কের স্বাস্থ্য","mission_briefing":"আমাদের শরীরের শিরা-উপশিরা যেমন চামড়ার নিচে লুকিয়ে থাকে, মাটির নিচের পাওয়ার কেবিলও (Underground Cable) ঠিক তাই। বাইরে থেকে এদের দেখা যায় না, তাই এদের সমস্যা ধরা সবচেয়ে কঠিন। অথচ একটা কেবিল ফল্ট মানে পুরো এলাকা অন্ধকার। আজকের মিশনে আমরা মাটির নিচের এই অদৃশ্য নেটওয়ার্কের স্বাস্থ্য পরীক্ষা করব। মেগার থেকে হাই-পট (Hi-Pot) টেস্ট—শিখব কীভাবে মাটির গভীরের খবর বের করে আনতে হয়।","sections":[{"title":"আন্ডারগ্রাউন্ড কেবিলের ডায়াগনস্টিক টেস্ট","image_name":"/images/loader/cable94_phase.webp","points":[{"item_name":"১. কন্টিনিউটি এবং ফেজ আইডেন্টিফিকেশন","image_name":"/images/loader/cable94_phase.webp","specifications":"মাল্টিমিটার বা ল্যাম্প-ব্যাটারি সেট দিয়ে পরীক্ষা করা হয়। এক প্রান্ত শর্ট করে অন্য প্রান্ত থেকে মাপা হয়।","importance":"কেবিল জয়েন্ট করার সময় মিস্ত্রিরা অনেক সময় ফেজ গুলিয়ে ফেলে (যেমন: লাল তারের সাথে হলুদ তার জুড়ে দেওয়া)। ফেজ আইডেন্টিফিকেশন নিশ্চিত করে যে সোর্সের ''R'' ফেজ লোডের ''R'' ফেজেই পৌঁছেছে। আর কন্টিনিউটি টেস্ট নিশ্চিত করে তারটি মাঝপথে ছেঁড়া নেই।","daily_check":"টেস্টের আগে কেবিলের দুই প্রান্তের আর্মার (Armour) বা আর্থিং খুলে আলাদা করে নিন।","image_caption":"ফেজ · কন্টিনিউটি"},{"item_name":"২. ইনসুলেশন রেজিস্ট্যান্স (IR) টেস্ট","image_name":"/images/loader/cable94_megger.webp","specifications":"এইচটি (HT) কেবিলের জন্য ৫০০০ ভোল্ট (5kV) মেগার এবং এলটি (LT) কেবিলের জন্য ৫০০/১০০০ ভোল্ট মেগার ব্যবহার করা হয়।","importance":"এটি কেবিলের প্রাথমিক চেক-আপ। আমরা ফেজ-টু-আর্থ (Phase-to-Earth) এবং ফেজ-টু-ফেজ (Phase-to-Phase) ইনসুলেশন মাপি। যদি ভ্যালু মেগা-ওহম (MΩ) রেঞ্জে না আসে, তবে কেবিল চার্জ করা বিপজ্জনক।","daily_check":"বৃষ্টির সময় বা কেবিলের মাথা ভিজে থাকলে মেগার ভ্যালু ভুল আসতে পারে। তাই হিট গান দিয়ে টার্মিনেশন শুকিয়ে নিন।","image_caption":"কেবিল মেগার · IR"},{"item_name":"৩. হাই-পট (Hi-Pot) টেস্ট: আসল অগ্নিপরীক্ষা","image_name":"/images/loader/cable94_vlf.webp","specifications":"আধুনিক নিয়মে VLF (Very Low Frequency) কিট ব্যবহার করা হয়। এতে কেবিলের রেটেড ভোল্টেজের চেয়ে দেড় থেকে দ্বিগুণ বেশি ভোল্টেজ দিয়ে নির্দিষ্ট সময় (যেমন ১৫ মিনিট) ধরে রাখা হয়।","importance":"মেগার টেস্টে অনেক সময় ছোটখাটো লিক বা দুর্বলতা ধরা পড়ে না। হাই-পট টেস্টে উচ্চ ভোল্টেজ প্রয়োগ করে দেখা হয় ইনসুলেশন সেই চাপ নিতে পারছে কিনা। যদি কেবিলের কোথাও দুর্বল জয়েন্ট বা পাংচার থাকে, তবে হাই-পট টেস্টে তা ফেল করবে।","daily_check":"হাই-পট টেস্টের সময় কেবিলের আশেপাশে কাউকে থাকতে দেবেন না। এটি অত্যন্ত বিপজ্জনক।","image_caption":"VLF হাই-পট"},{"item_name":"৪. শীথ (Sheath) ইন্টিগ্রিটি টেস্ট","image_name":"/images/loader/cable94_sheath.webp","specifications":"কেবিলের বাইরের কালো কভার বা জ্যাকেটের স্বাস্থ্য পরীক্ষা।","importance":"মাটির নিচে ইঁদুর বা উইপোকা অনেক সময় কেবিলের বাইরের আস্তরণ খেয়ে ফেলে, যার ফলে ভেতরে জল ঢুকে কেবিল নষ্ট হয়। এই টেস্টটি সেই বাইরের ইনজুরি খুঁজে বের করে।","daily_check":"ভিজ্যুয়াল চেক করুন কোথাও জ্যাকেট কেটে গেছে কিনা।","image_caption":"শীথ ইন্টিগ্রিটি"}],"image_caption":"ফেজ · কন্টিনিউটি"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. ডিসচার্জ না করলে মৃত্যু: কেবিল একটি বিশাল ক্যাপাসিটর। টেস্ট করার পর এটি মারাত্মক চার্জ ধরে রাখে। মেগার বা হাই-পট বন্ধ করার পর অন্তত ৫ মিনিট ডিসচার্জ রড দিয়ে কেবিলটি আর্থ করে রাখুন। ডিসচার্জ না করে হাত দেবেন না!","২. গার্ড টার্মিনাল (Guard Terminal): কেবিলের মুখে যদি খুব ধুলো বা আর্দ্রতা থাকে, তবে মেগারের ''G'' টার্মিনালটি ইনসুলেশনের ওপর জড়িয়ে দিন। এটি সারফেস লিকেজ কারেন্ট বাইপাস করে সঠিক রিডিং দেবে।","৩. উল্টো দিক থেকে চেক: ফল্ট খোঁজার সময় সবসময় লোড সাইড থেকে সোর্স সাইডের দিকে চেক করা বুদ্ধিমানের কাজ।","৪. জয়েন্টেই যত দোষ: কেবিলের মাঝখানে কোথাও জয়েন্ট থাকলে সেখানেই ফল্ট হওয়ার সম্ভাবনা ৯০%। টেস্টের সময় জয়েন্টগুলোর দিকে বিশেষ নজর দিন।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"নতুন কেবিল ড্রাম থেকে খুলেছি, টেস্ট করার দরকার নেই।","reality":"ভুল! পরিবহনের সময় বা ড্রাম গড়ানোর সময় ভেতরের ইনসুলেশন ক্ষতিগ্রস্ত হতে পারে। ইনস্টল করার আগে এবং পরে—উভয় সময়েই টেস্ট বাধ্যতামূলক।","verdict":"বিশ্বাস ভালো, কিন্তু টেস্ট আরও ভালো!"},{"myth":"ডিসি (DC) হাই-পট টেস্ট সব কেবিলেই করা যায়।","reality":"পুরানো XLPE কেবিলে ডিসি হাই-পট টেস্ট করা ক্ষতিকর। এটি কেবিলের ইনসুলেশনে ''স্পেস চার্জ'' তৈরি করে আয়ু কমিয়ে দেয়। তাই এখন VLF (AC) টেস্ট করার পরামর্শ দেওয়া হয়।","verdict":"XLPE কেবিলে ডিসি বর্জন করুন।"}],"image_name":"/images/loader/cable94_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · কেবিল"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"ওয়াটার ট্রিয়িং (Water Treeing)","content":"XLPE কেবিলের প্রধান শত্রু হলো ''ওয়াটার ট্রি''। কেবিলের ইনসুলেশনের ভেতরে অতিরিদ্র আর্দ্রতা ঢুকলে গাছের শিকড়ের মতো দেখতে সূক্ষ্ম ফাটল তৈরি হয়, যা ধীরে ধীরে কেবিলকে নষ্ট করে দেয়। VLF টেস্ট এটি ধরতে সাহায্য করে।"},{"title":"কেন ০.১ হার্টজ (0.1 Hz)?","content":"সাধারণ ৫০ হার্টজ ফ্রিকোয়েন্সিতে কয়েক কিলোমিটার লম্বা কেবিল টেস্ট করতে বিশাল আকারের ট্রান্সফরমার লাগত (বিশাল কারেন্ট লাগত)। ফ্রিকোয়েন্সি কমিয়ে ০.১ হার্টজ করলে (VLF) খুব ছোট মেশিন দিয়েই কেবিল চার্জ করা যায় এবং নিখুঁত টেস্ট করা সম্ভব হয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.4' AND language = 'bn';

-- Lesson 9.5
UPDATE training_chapters
SET
  content = '{"level_id":"9.5","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"আর্থিং সিস্টেম টেস্টিং: অদৃশ্য রক্ষকের শক্তি পরীক্ষা","mission_briefing":"একটি বিশাল বহুতল ভবন যেমন মাটির নিচের ভিত্তির ওপর দাঁড়িয়ে থাকে, ঠিক তেমনই পুরো ইলেকট্রিক্যাল সিস্টেমের সুরক্ষার ভিত্তি হলো ''আর্থিং''। এটি হলো সেই অদৃশ্য ড্রেন, যা ফল্ট কারেন্টকে নিরাপদে মাটিতে নামিয়ে দেয়। যদি এই ড্রেন জ্যাম হয়ে থাকে, তবে শর্ট সার্কিট হলে ফিউজ বা ব্রেকার কাজ করবে না, আর যন্ত্রপাতি বা মানুষের জীবন ঝুঁকিতে পড়বে। আজকের মিশনে আমরা আর্থ টেস্টার দিয়ে এই রক্ষকের ফিটনেস পরীক্ষা করব।","sections":[{"title":"আর্থ পিট এবং সিস্টেম টেস্টিং পদ্ধতি","image_name":"/images/loader/earth95_pit.webp","points":[{"item_name":"১. আর্থ পিট এবং স্ট্রিপের ভিজ্যুয়াল চেক","image_name":"/images/loader/earth95_pit.webp","specifications":"আর্থ পিটের ঢাকনা খুলে দেখুন। স্ট্রিপ এবং ইলেক্ট্রোডের সংযোগস্থলে কোনো জং (Rust) বা ফাটল আছে কিনা।","importance":"মাটির নিচে কানেকশন লুজ হয়ে গেলে বা স্ট্রিপ পচে গেলে আর্থিং কাজ করবে না। বর্ষাকালে বা নোনা আবহাওয়ায় এই ক্ষয় বেশি হয়। একটি ভাঙা আর্থ স্ট্রিপ মানে আপনার সুরক্ষা কবচ অকেজো।","daily_check":"আর্থ পিটের ভেতরে জল দেওয়ার ফানেলটি পরিষ্কার আছে কিনা দেখুন। কানেকশন বোল্টগুলো টাইট আছে কিনা রেঞ্চ দিয়ে চেক করুন।","image_caption":"পিট ভিজ্যুয়াল · জং"},{"item_name":"২. ৩-পয়েন্ট মেথড (Fall of Potential)","image_name":"/images/loader/earth95_3point.webp","specifications":"এটিই স্ট্যান্ডার্ড পদ্ধতি। এতে তিনটি টার্মিনাল থাকে: E (Earth Electrode), P (Potential Spike), এবং C (Current Spike)। টেস্টের সময় P এবং C স্পাইক দুটিকে মেইন ইলেকট্রোড থেকে নির্দিষ্ট দূরত্বে সরলরেখায় মাটিতে পুঁতে দেওয়া হয়।","importance":"এই টেস্ট আমাদের সঠিক আর্থ রেজিস্ট্যান্স ভ্যালু দেয়। সাবস্টেশনের জন্য এই মান ১ ওহম (1 Ohm) এর নিচে এবং ডিস্ট্রিবিউশন পোলের জন্য ৫ ওহম (5 Ohm) এর নিচে হওয়া বাঞ্ছনীয়।","daily_check":"স্পাইকগুলো মাটিতে শক্তভাবে পুঁতে দিন। যদি মাটি খুব শুকনো হয়, তবে স্পাইকের গোড়ায় সামান্য জল দিন ভালো কন্টাক্টের জন্য।","image_caption":"৩-পয়েন্ট · ≤১ Ω"},{"item_name":"৩. ক্ল্যাম্প-অন আর্থ টেস্টার (Clamp-on Earth Tester)","image_name":"/images/loader/earth95_clamp.webp","specifications":"মাটিতে গর্ত না খুঁড়ে বা তার না খুলে এটি দিয়ে টেস্ট করা যায়। এটি দেখতে ক্ল্যাম্প মিটারের মতো।","importance":"শহরের কনক্রিট এলাকায় যেখানে মাটিতে স্পাইক পোঁতা সম্ভব নয়, সেখানে এটি খুব কাজে দেয়। তবে এটি শুধুমাত্র মাল্টি-গ্রাউন্ডেড সিস্টেমেই (যেখানে অনেকগুলো আর্থিং প্যারালাল করা আছে) সঠিক কাজ করে।","daily_check":"ক্ল্যাম্পের মুখ (Jaws) যেন পরিষ্কার থাকে এবং পুরোপুরি বন্ধ হয়।","image_caption":"ক্ল্যাম্প-অন আর্থ"},{"item_name":"৪. গ্রিড কন্টিনিউটি টেস্ট","image_name":"/images/loader/earth95_grid.webp","specifications":"সাবস্টেশনের রাইজার (Riser) এবং মেইন আর্থ ম্যাটের মধ্যে সংযোগ পরীক্ষা।","importance":"ট্রান্সফরমার বা ব্রেকারের বডি আর্থিং পয়েন্ট থেকে মাটির নিচের জালি (Mesh) পর্যন্ত তারটি কোথাও ছিঁড়ে গেছে কিনা তা নিশ্চিত করতে লো-রেজিস্ট্যান্স ওহম মিটার দিয়ে এটি মাপা হয়।","daily_check":"আর্থ ফ্ল্যাট বা তারের রঙ (সবুজ বা কালো) দেখে এবং হাত দিয়ে টেনে ফিজিক্যাল চেক করুন।","image_caption":"গ্রিড কন্টিনিউটি"}],"image_caption":"পিট ভিজ্যুয়াল · জং"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. লিংক খুলতে ভুলবেন না: আর্থ পিটের রেজিস্ট্যান্স মাপার সময় ইকুইপমেন্ট থেকে আসা আর্থ স্ট্রিপটি (Test Link) খুলে আলাদা করে নিন। নাহলে আপনি প্যারালাল রেজিস্ট্যান্স মাপবেন, যা সঠিক পিটের ভ্যালু নয়।","২. ৬২% নিয়ম: ৩-পয়েন্ট টেস্টে, কারেন্ট স্পাইক (C) যতটা দূরে বসাবেন, পটেনশিয়াল স্পাইক (P) তার ৬২% দূরত্বে বসালে সবচেয়ে সঠিক রেজাল্ট পাওয়া যায়।","৩. ভেজা মাটি মানেই ভালো নয়: বৃষ্টির পরপরই টেস্ট করলে রেজাল্ট খুব ভালো আসবে, কিন্তু সেটা স্থায়ী নয়। সবচেয়ে শুকনো সময়ে (Summer) টেস্ট করাই আসল পরীক্ষা।","৪. লবণ ও কয়লা: পিটের ভ্যালু বেশি আসলে লবণ, কয়লা বা বেন্টোনাইট পাউডার দিয়ে ট্রিটমেন্ট করুন এবং জল দিন।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"এক বালতি জল ঢেলে দিলেই আর্থিং ভালো হয়ে যায়।","reality":"জল ঢাললে সাময়িকভাবে রেজিস্ট্যান্স কমে ঠিকই, কিন্তু মাটি শুকিয়ে গেলে আবার তা বেড়ে যায়। স্থায়ী সমাধানের জন্য কেমিক্যাল আর্থিং বা রডের গভীরতা বাড়ানো প্রয়োজন।","verdict":"জল কোনো পার্মানেন্ট সলিউশন নয়।"},{"myth":"সবুজ তার লাগানো মানেই আমি সেফ।","reality":"সবুজ তারটি যদি মাটির নিচে ভাঙা রডের সাথে যুক্ত থাকে, তবে তার থাকা না থাকা সমান। টেস্টার দিয়ে মাপা ছাড়া নিশ্চিত হওয়া বোকামি।"}],"image_name":"/images/loader/earth95_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · আর্থিং"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"স্টেপ এবং টাচ পটেনশিয়াল (Step & Touch Potential)","content":"আর্থিং ডিজাইনের মূল উদ্দেশ্য শুধু যন্ত্রপাতি বাঁচানো নয়, মানুষের প্রাণ বাঁচানো। হাই ভোল্টেজ ফল্টের সময় মাটির ভোল্টেজ বেড়ে যায়। তখন একজন মানুষের দুই পায়ের মাঝের ভোল্টেজ পার্থক্যকে ''স্টেপ পটেনশিয়াল'' এবং হাত ও পায়ের মাঝের পার্থক্যকে ''টাচ পটেনশিয়াল'' বলে। ভালো আর্থিং ডিজাইন এই ভোল্টেজকে নিরাপদ সীমার মধ্যে রাখে।"},{"title":"সয়েল রেজিষ্টিভিটি (Soil Resistivity)","content":"আর্থিং রড পোঁতার আগে মাটির ধরন (বেলে, দোঁয়াশ, বা পাথুরে) পরীক্ষা করা জরুরি। একে ''সয়েল রেজিষ্টিভিটি টেস্ট'' বলে (Wenner 4-point method)। পাথুরে মাটিতে ১০টা রড পুঁতে যা কাজ হবে, ভেজা মাটিতে ১টা রডেই তার চেয়ে ভালো কাজ হতে পারে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.5' AND language = 'bn';

-- Lesson 9.6
UPDATE training_chapters
SET
  content = '{"level_id":"9.6","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"ইনসুলেটর টেস্টিং: প্রহরীর শক্তি পরীক্ষা","mission_briefing":"ইনসুলেটর হলো আমাদের হাই ভোল্টেজ লাইনের ''সীমান্ত প্রহরী''। এরা হাজার হাজার ভোল্টের লাইভ তারকে শক্ত করে ধরে রাখে, কিন্তু সেই ভোল্টেজকে টাওয়ার বা পোলে নামতে দেয় না। কিন্তু রোদ, ঝড় আর ধুলোবালি খেতে খেতে এই প্রহরীও দুর্বল হয়ে পড়ে। যদি ইনসুলেটর লিক (Leak) করে, তবে পুরো টাওয়ার লাইভ হয়ে যাবে, যা নিচে থাকা মানুষের জন্য মরণফাঁদ। আজকের মিশনে আমরা দেখব এই ইনসুলেটররা তাদের ডিউটি ঠিকমতো করছে কিনা।","sections":[{"title":"ইনসুলেটর পরীক্ষার আধুনিক ও সনাতন পদ্ধতি","image_name":"/images/loader/insul96_visual.webp","points":[{"item_name":"১. ভিজ্যুয়াল ইন্সপেকশন (বাইনোকুলার দিয়ে)","image_name":"/images/loader/insul96_visual.webp","specifications":"মাটিতে দাঁড়িয়ে হাই-পাওয়ার বাইনোকুলার দিয়ে টাওয়ারের ওপরের ইনসুলেটর স্ট্রিং চেক করা।","importance":"সবচেয়ে সহজ কিন্তু কার্যকর। দেখতে হবে পোর্সেলিন ডিস্কের কোনো অংশ ভেঙে গেছে কিনা (Chipped/Broken), কোনো পোড়া দাগ (Flashover mark) আছে কিনা, বা অতিরিক্ত পাখির মল বা ধুলো জমেছে কিনা। পলিমার ইনসুলেটরের ক্ষেত্রে দেখতে হবে তার ওপরের আস্তরণ বা স্কার্ট ফেটে গেছে কিনা।","daily_check":"বৃষ্টির পরে বা ঝড়ের পরে এই চেক খুব জরুরি।","image_caption":"ভিজ্যুয়াল · চিপ · ফ্ল্যাশ"},{"item_name":"২. ইনসুলেশন রেজিস্ট্যান্স (IR) টেস্ট","image_name":"/images/loader/insul96_megger.webp","specifications":"লাইন শাটডাউন নিয়ে ৫০০০ ভোল্ট (5kV) মেগার দিয়ে প্রতিটি ডিস্ক আলাদাভাবে টেস্ট করা হয়।","importance":"একটি ভালো ইনসুলেটর ডিস্কের রেজিস্ট্যান্স অবশ্যই ৫০০ মেগা-ওহম বা তার বেশি হওয়া উচিত। যদি কোনো ডিস্কের রিডিং খুব কম বা শূন্য আসে, তবে সেটিকে ''পাংচারড'' (Punctured) বা মৃত বলে ধরে নেওয়া হয় এবং পুরো স্ট্রিং বদলাতে হতে পারে।","daily_check":"টেস্টের আগে ইনসুলেটরটি শুকনো কাপড় দিয়ে মুছে পরিষ্কার করে নিন।","image_caption":"ডিস্ক মেগার · ≥৫০০ MΩ"},{"item_name":"৩. পিআইডি (PID) টেস্টিং কিট","image_name":"/images/loader/insul96_pid.webp","specifications":"পাংচার ইনসুলেটর ডিটেক্টর (PID)। এটি দিয়ে লাইভ লাইনেও (সতর্কতার সাথে) ইনসুলেটর চেক করা সম্ভব।","importance":"পোর্সেলিন ইনসুলেটরের ভেতরে অদৃশ্য ফাটল থাকলে তা বাইরে থেকে বোঝা যায় না। PID কিট ইলেকট্রোম্যাগনেটিক ফিল্ড মেপে বলে দেয় কোন ডিস্কটি নষ্ট হয়ে গেছে।","daily_check":"এটি ব্যবহারের জন্য বিশেষ ট্রেনিং এবং হট স্টিক (Hot Stick) ব্যবহারের অভিজ্ঞতা প্রয়োজন।","image_caption":"PID কিট"},{"item_name":"৪. করোনা ক্যামেরা (Corona Camera)","image_name":"/images/loader/insul96_corona.webp","specifications":"এটি একটি বিশেষ ধরনের ইউভি (UV) ক্যামেরা যা দিনের আলোতেও করোনার ডিসচার্জ দেখতে পায়।","importance":"ইনসুলেটরের গায়ে যদি সূক্ষ্ম ক্র্যাক বা দূষণ থাকে, তবে সেখানে ''করোনা ডিসচার্জ'' (বেগুনি আভা) হয় যা খালি চোখে দেখা যায় না। এই ক্যামেরা সেই অদৃশ্য বিপদকে স্ক্রিনে ফুটিয়ে তোলে। এটি প্রিভেন্টিভ মেইনটেন্যান্সের জন্য সেরা টুল।","daily_check":"ক্যামেরার লেন্স পরিষ্কার রাখা এবং ফোকাস ঠিক করা জরুরি।","image_caption":"করোনা ক্যামেরা · UV"}],"image_caption":"ভিজ্যুয়াল · চিপ · ফ্ল্যাশ"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. পরিষ্কার না করলে রিডিং ভুল: ইনসুলেটরের গায়ে যদি ধুলো, কার্বন বা লবণের স্তর জমে থাকে, তবে মেগার ভ্যালু অনেক কম আসবে। টেস্ট করার আগে ''ক্লিনিং সলভেন্ট'' বা নিদেনপক্ষে শুকনো কাপড় দিয়ে ভালো করে মুছুন।","২. বৃষ্টির দিনে টেস্ট নিষেধ: বাতাসে আর্দ্রতা বেশি থাকলে ইনসুলেটরের সারফেস দিয়ে লিকেজ কারেন্ট বাড়ে, যা আপনাকে ভুল তথ্য দেবে। রৌদ্রোজ্জ্বল দিনই ইনসুলেটর টেস্টিংয়ের জন্য সেরা।","৩. হিসহিস শব্দ শুনুন: অনেক সময় কোনো মেশিন ছাড়াই কান পেতে লাইন চেক করা যায়। পোলের কাছে দাঁড়িয়ে যদি জোর ''হিসহিস'' বা ''চড়চড়'' শব্দ পান, বুঝবেন ইনসুলেটর লিক করছে বা ট্র্যাকিং হচ্ছে।","৪. গ্লাস ইনসুলেটর: কাঁচের ইনসুলেটর ফেটে গেলে পুরোটা ঝুরঝুর করে ভেঙে পড়ে না, কিন্তু এর যান্ত্রিক শক্তি কমে যায়। তাই ভাঙা গ্লাস দেখলেই সাবধান।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"পলিমার ইনসুলেটর পোর্সেলিনের চেয়ে হালকা, তাই এগুলো দুর্বল।","reality":"ওজন দিয়ে শক্তি বিচার করবেন না। পলিমার ইনসুলেটর ওজনে হালকা হলেও এর ''হাইড্রোফোবিসিটি'' (জল তাড়ানোর ক্ষমতা) পোর্সেলিনের চেয়ে অনেক ভালো, এবং এটি সহজে ভাঙে না। দূষিত এলাকায় পলিমারই সেরা।","verdict":"হালকা মানেই ঠুনকো নয়।"},{"myth":"একটা ডিস্ক ভেঙে গেছে, বাকিগুলো তো ঠিক আছে, লাইন চলবে।","reality":"১১ কেভি লাইনে ৩টি ডিস্কের ১টি ভেঙে গেলে বাকি দুটির ওপর ভোল্টেজের চাপ বেড়ে যায়। এতে যেকোনো সময় ফ্ল্যাশওভার হয়ে লাইন ট্রিপ করতে পারে। ঝুঁকি না নিয়ে বদলে ফেলাই বুদ্ধিমানের কাজ।","verdict":"চেইন ততটাই শক্তিশালী যতটা তার দুর্বলতম কড়া।"}],"image_name":"/images/loader/insul96_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ইনসুলেটর"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"ক্রিপেজ ডিস্টেন্স (Creepage Distance)","content":"ইনসুলেটরের গায়ে কেন ঢেউখেলানো বা খাঁজকাটা (Ribs) থাকে? সোজা টিউব কেন হয় না? কারণ হলো ''ক্রিপেজ ডিস্টেন্স''। কারেন্ট যেন ইনসুলেটরের গা বেয়ে সহজে পার হতে না পারে, তাই পথটিকে আঁকাবাঁকা করে লম্বা করা হয়। খাঁজগুলো এই পথ বা ডিস্টেন্স বাড়িয়ে দেয়, ফলে লিকেজ কারেন্ট কমে যায়।"},{"title":"করোনা ইফেক্ট (Corona Effect)","content":"হাই ভোল্টেজে ইনসুলেটরের চারপাশের বাতাস আয়নাইজড হয়ে বিদ্যুৎ পরিবাহী হয়ে ওঠে, একে করোনা বলে। এটি ইনসুলেটরকে খেয়ে ফেলে (Erosion) এবং রেডিও সিগন্যালে নয়েজ তৈরি করে। করোনা রিং ব্যবহার করে এই ইলেকট্রিক্যাল স্ট্রেস কমানো হয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.6' AND language = 'bn';

-- Lesson 9.7
UPDATE training_chapters
SET
  content = '{"level_id":"9.7","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"রিলে টেস্টিং: মস্তিষ্কের কার্যকারিতা পরীক্ষা","mission_briefing":"সার্কিট ব্রেকার যদি সাবস্টেশনের ''হাত-পা'' হয়, তবে প্রোটেকশন রিলে (Relay) হলো তার ''মস্তিষ্ক''। সিটি (CT) এবং পিটি (PT) থেকে সিগন্যাল নিয়ে রিলে সিদ্ধান্ত নেয় কখন ব্রেকারকে ট্রিপ করাতে হবে। রিলে যদি ভুল সিদ্ধান্ত নেয় বা ঘুমিয়ে থাকে, তবে চোখের সামনে সাবস্টেশন পুড়ে যাবে। আজকের মিশনে আমরা ''সেকেন্ডারি ইনজেকশন কিট'' দিয়ে এই মস্তিষ্কের আইকিউ (IQ) টেস্ট করব। দেখব সে ঠিক সময়ে সঠিক সিদ্ধান্ত নিতে পারে কিনা।","sections":[{"title":"রিলে টেস্টিং-এর ধাপসমূহ","image_name":"/images/loader/relay97_visual.webp","points":[{"item_name":"১. ভিজ্যুয়াল চেকআপ ও সেটিংস ভেরিফিকেশন","image_name":"/images/loader/relay97_visual.webp","specifications":"রিলে কভারের কাঁচ পরিষ্কার আছে কিনা, কোনো এরর (Error) লাইট বা ''Watchdog'' এলার্ম জ্বলছে কিনা দেখুন।","importance":"আধুনিক নিউমেরিক্যাল রিলেতে ডিসপ্লের দিকে তাকালেই অর্ধেক রোগ ধরা পড়ে। ব্যাটারি লো, মেমোরি ফুল বা ইন্টারনাল ফল্ট থাকলে রিলে নিজেই লাল বাতি জ্বালিয়ে সিগন্যাল দেয়। কাজ শুরুর আগে নিশ্চিত হোন রিলের সেটিংস (PSM, TMS) আপনার চার্টের সাথে মিলছে।","daily_check":"রিলের পেছনের টার্মিনাল ব্লকগুলোতে কোনো পোড়া দাগ বা লুজ কানেকশন আছে কিনা দেখুন।","image_caption":"সেটিংস · PSM/TMS"},{"item_name":"২. পিক-আপ টেস্ট (Pick-up Test)","image_name":"/images/loader/relay97_pickup.webp","specifications":"সেকেন্ডারি ইনজেকশন কিট ব্যবহার করে কৃত্রিমভাবে রিলের কয়েলে কারেন্ট দেওয়া হয়।","importance":"ধরুন রিলে সেট করা আছে ৫ অ্যাম্পিয়ারে। আমরা দেখব ঠিক ৫ অ্যাম্পিয়ার কারেন্ট দিলে রিলের ''স্টার্ট'' বা ''পিক-আপ'' লাইট জ্বলে কিনা। যদি ৪ অ্যাম্পিয়ারে জ্বলে বা ৬ অ্যাম্পিয়ারেও না জ্বলে, তবে বুঝতে হবে রিলের সেন্সরে গণ্ডগোল আছে।","daily_check":"কিটের কানেকশন ঠিকমতো কারেন্ট টার্মিনালে লেগেছে কিনা চেক করুন।","image_caption":"পিক-আপ · ইনজেকশন"},{"item_name":"৩. অপারেটিং টাইম টেস্ট (Timing Test)","image_name":"/images/loader/relay97_timing.webp","specifications":"ফল্ট কারেন্ট দিলে রিলে কত সেকেন্ড পর ট্রিপ কমান্ড দেয়, তা মাপা।","importance":"রিলে যদি আইডিএমটি (IDMT) মোডে থাকে, তবে কারেন্ট যত বেশি হবে, ট্রিপ টাইম তত কম হবে। ২ গুণ কারেন্টে যদি ১০ সেকেন্ডে ট্রিপ করে, তবে ১০ গুণ কারেন্টে হয়তো ১ সেকেন্ডে ট্রিপ করবে। এই টাইমিং চার্টের সাথে না মিললে ''কোঅর্ডিনেশন'' ফেল করবে।","daily_check":"টেস্ট করার সময় টাইমার যেন অটোমেটিক স্টার্ট এবং স্টপ হয়, ম্যানুয়ালি স্টপওয়াচ ধরলে ভুল হবে।","image_caption":"টাইমিং · IDMT"},{"item_name":"৪. ট্রিপ কন্টাক্ট চেক","image_name":"/images/loader/relay97_trip.webp","specifications":"রিলে অপারেট করলে তার আউটপুট কন্টাক্ট (NO/NC) ঠিকমতো কাজ করছে কিনা দেখা।","importance":"রিলে ডিসপ্লেতে দেখাল ''ট্রিপ'', কিন্তু পেছনের কন্টাক্ট জং ধরার কারণে সিগন্যাল ব্রেকার পর্যন্ত পৌঁছাল না—এমন ঘটনা প্রায়ই ঘটে। তাই মাল্টিমিটার দিয়ে কন্টাক্ট ক্লোজিং নিশ্চিত করতে হয়।","daily_check":"মাস্টার ট্রিপ রিলে (Master Trip Relay - 86) কাজ করছে কিনা সেটাও দেখে নিন।","image_caption":"ট্রিপ কন্টাক্ট · NO/NC"}],"image_caption":"সেটিংস · PSM/TMS"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. সিটি (CT) শর্টিং সবার আগে: লাইভ লাইনে রিলে নিয়ে কাজ করার সময় বা রিলে খোলার আগে সিটি লিংক (CT Link) অবশ্যই শর্ট করতে হবে। সিটি ওপেন করলে সেকেন্ডারিতে হাজার হাজার ভোল্ট তৈরি হয়ে বিস্ফোরণ ঘটতে পারে। এটা লাইনম্যানের জীবনের ১ নম্বর রুল।","২. ডিসি সাপ্লাই ছাড়া রিলে মৃত: টেস্ট করার আগে রিলের অক্সিলারি সাপ্লাই (Auxiliary DC Supply) ঠিক আছে কিনা দেখে নিন। ডিসি ফিউজ কাটা থাকলে রিলে কাজ করবে না।","৩. ইলেক্ট্রোস্ট্যাটিক ডিসচার্জ (ESD): মডার্ন রিলে হলো কম্পিউটার। আপনার শরীরের স্ট্যাটিক চার্জ এর মাদারবোর্ড নষ্ট করতে পারে। তাই রিলের ভেতরের কার্ড ধরার আগে নিজেকে আর্থ করে নিন।","৪. অটো-রিক্লোজ বন্ধ রাখুন: টেস্ট করার সময় ''Auto-Reclose'' ফাংশন অফ বা ব্লক করে রাখুন, নাহলে ব্রেকার বারবার অন-অফ হতে পারে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"রিলেতে আলো জ্বলছে মানেই রিলে ঠিক আছে।","reality":"মোবাইলের স্ক্রিন জ্বলছে মানেই কি টাচস্ক্রিন কাজ করছে? না। রিলের ''Power On'' এলইডি জ্বললেও এর সেন্সিং কয়েল বা আউটপুট কার্ড খারাপ থাকতে পারে। ইনজেকশন টেস্ট ছাড়া নিশ্চিত হওয়া অসম্ভব।","verdict":"আলো দেখে ভুলবেন না।"},{"myth":"ইলেক্ট্রো-মেকানিক্যাল (চাকতি ঘুরানো) রিলে এখন অচল।","reality":"যদিও ডিজিটাল রিলে অনেক বেশি স্মার্ট, কিন্তু পুরানো ইলেক্ট্রো-মেকানিক্যাল রিলে অত্যন্ত মজবুত এবং সাইবার অ্যাটাক বা সফটওয়্যার হ্যাং হওয়া থেকে মুক্ত। অনেক জায়গায় ব্যাক-আপ হিসেবে এগুলো আজও সেরা।"}],"image_name":"/images/loader/relay97_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · রিলে"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"PSM এবং TMS","content":"রিলে সেটিংয়ের দুটি প্রধান প্যারামিটার। PSM (Plug Setting Multiplier) ঠিক করে কত কারেন্টে রিলে কাজ শুরু করবে। আর TMS (Time Multiplier Setting) ঠিক করে সেই কারেন্টে রিলে কত দ্রুত ট্রিপ করবে। এই দুটির গুণফলেই তৈরি হয় রিলের ''কার্ভ'' (Curve)।"},{"title":"ডিস্টার্বেন্স রেকর্ডার (DR)","content":"নিউমেরিক্যাল রিলের সবচেয়ে বড় সুবিধা হলো DR। ফল্ট হওয়ার ঠিক আগের এবং পরের কয়েক সেকেন্ডের কারেন্ট ও ভোল্টেজের ওয়েভফর্ম এটি মেমোরিতে সেভ করে রাখে। পোস্ট-মর্টেম বা ফল্ট অ্যানালাইসিসের জন্য এটি ব্ল্যাকবক্সের মতো কাজ করে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.7' AND language = 'bn';

-- Lesson 9.8
UPDATE training_chapters
SET
  content = '{"level_id":"9.8","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"ব্যাটারি এবং চার্জার টেস্টিং: জরুরি শক্তির উৎস","mission_briefing":"সাবস্টেশনে যদি এসি (AC) সাপ্লাই ফেল করে, তখন পুরো সিস্টেমকে বাঁচিয়ে রাখে কে? উত্তর হলো ডিসি (DC) ব্যাটারি ব্যাংক। সার্কিট ব্রেকার ট্রিপ করানো থেকে শুরু করে রিলের কাজ—সবকিছুই এই ব্যাটারির ওপর নির্ভরশীল। একে বলা যায় সাবস্টেশনের ''লাইফ সাপোর্ট সিস্টেম''। ব্যাটারি ফেইল করা মানে বিপদের সময় ব্রেকার কাজ করবে না। আজকের মিশনে আমরা এই সাইলেন্ট হিরোর স্বাস্থ্য পরীক্ষা করব।","sections":[{"title":"ব্যাটারি ও চার্জার রক্ষণাবেক্ষণের ধাপ","image_name":"/images/loader/batt98_volt.webp","points":[{"item_name":"১. সেল ভোল্টেজ মেজারমেন্ট","image_name":"/images/loader/batt98_volt.webp","specifications":"মাল্টিমিটার ডিসি ভোল্টে সেট করে প্রতিটি সেলের ভোল্টেজ আলাদাভাবে মাপতে হয়।","importance":"একটি ২ ভোল্টের সেলের ভোল্টেজ যদি ১.৮ বা তার নিচে নেমে যায়, তবে সেটি পুরো ব্যাটারি ব্যাংকের পারফরম্যান্স কমিয়ে দেবে। চার্জার ''ফ্লোট'' (Float) মোডে থাকলে ভোল্টেজ কত এবং ''বুস্ট'' (Boost) মোডে থাকলে কত, তা চার্টের সাথে মিলিয়ে দেখা জরুরি।","daily_check":"কোনো সেল অন্যগুলোর তুলনায় বেশি গরম হচ্ছে কিনা হাত দিয়ে (গ্লাভস পরে) দেখুন।","image_caption":"সেল ভোল্টেজ · ফ্লোট/বুস্ট"},{"item_name":"২. স্পেসিফিক গ্র্যাভিটি (Specific Gravity) টেস্ট","image_name":"/images/loader/batt98_sg.webp","specifications":"হাইড্রোমিটার (Hydrometer) দিয়ে লিড-এসিড ব্যাটারির ইলেকট্রোলাইট বা এসিডের ঘনত্ব মাপা হয়।","importance":"এটি ব্যাটারির চার্জ অবস্থার সবচেয়ে নিখুঁত প্রমাণ। ফুল চার্জ অবস্থায় গ্র্যাভিটি ১.২০০ থেকে ১.২২০ এর মধ্যে থাকা উচিত। যদি কোনো সেলের গ্র্যাভিটি ১.১৫০ এর নিচে নামে, তবে বুঝতে হবে সেলটি দুর্বল বা ডেড হয়ে যাচ্ছে।","daily_check":"ইলেক্ট্রোলাইটের লেভেল কমে গেলে শুধুমাত্র ডিস্টিলড ওয়াটার (DM Water) যোগ করুন, এসিড নয়।","image_caption":"স্পেসিফিক গ্র্যাভিটি"},{"item_name":"৩. লোড ডিসচার্জ টেস্ট","image_name":"/images/loader/batt98_load.webp","specifications":"ব্যাটারি চার্জার বন্ধ করে একটি ডামি লোড (হিটার ব্যাংক) লাগিয়ে ব্যাটারিকে ডিসচার্জ করা হয়।","importance":"ভোল্টেজ ঠিক দেখালেই ব্যাটারি ভালো—এটা ভুল। লোড পড়লে ব্যাটারি কতক্ষণ ব্যাকআপ দিতে পারে, সেটা দেখাই আসল পরীক্ষা। একে ক্যাপাসিটি টেস্টও বলে।","daily_check":"এই টেস্ট করার সময় অবশ্যই ব্যাকআপ বা বিকল্প সোর্স রেডি রাখতে হবে।","image_caption":"লোড ডিসচার্জ · ক্যাপাসিটি"},{"item_name":"৪. ভিজ্যুয়াল চেক এবং টার্মিনাল টাইটনেস","image_name":"/images/loader/batt98_term.webp","specifications":"টার্মিনালে সাদা পাউডার (Sulfation) জমেছে কিনা এবং ব্যাটারির বডি ফুলে গেছে কিনা দেখা।","importance":"লুজ কানেকশন বা জং ধরা টার্মিনাল হাই রেজিস্ট্যান্স তৈরি করে, যা ইমার্জেন্সির সময় কারেন্ট প্রবাহে বাধা দেয়। সাদা জং বা ''সালফেশন'' ব্যাটারির ক্যানসার।","daily_check":"পেট্রোলিয়াম জেলি (Petroleum Jelly) লাগিয়ে টার্মিনাল সুরক্ষিত রাখুন। গ্রিজ ব্যবহার করবেন না।","image_caption":"টার্মিনাল · সালফেশন"}],"image_caption":"সেল ভোল্টেজ · ফ্লোট/বুস্ট"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. আগুনের খেলা নয়: ব্যাটারি রুমে চার্জিংয়ের সময় হাইড্রোজেন গ্যাস তৈরি হয় যা অত্যন্ত দাহ্য। সেখানে ধূমপান বা কোনো স্পার্ক তৈরি করা মানে বোমা ফাটানো। এক্সহস্ট ফ্যান সবসময় অন রাখুন।","২. জলের গুণমান: ব্যাটারিতে কলের জল বা মিনারেল ওয়াটার দেবেন না। এতে থাকা লোহা ও খনিজ ব্যাটারির প্লেট নষ্ট করে দেয়। সবসময় ল্যাবরেটরি গ্রেড ডিস্টিলড ওয়াটার ব্যবহার করুন।","৩. পাইলট সেল (Pilot Cell): সব সেলের গ্র্যাভিটি রোজ মাপা সম্ভব নয়। তাই একটি বা দুটি ''পাইলট সেল'' বেছে নিন এবং রোজ তাদের রিডিং নোট করুন। এতে পুরো ব্যাংকের অবস্থা বোঝা যায়।","৪. চার্জারের রিপল (Ripple): চার্জার থেকে আসা ডিসি কারেন্টে যেন এসি রিপল না থাকে। এসি ব্যাটারির প্লেটকে গরম করে আয়ু কমিয়ে দেয়।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"মেইনটেন্যান্স ফ্রি (Maintenance Free) ব্যাটারি মানে কোনো চেকআপই লাগবে না।","reality":"সবচেয়ে বড় মিথ্যা! মেইনটেন্যান্স ফ্রি মানে শুধু জল দিতে হবে না, কিন্তু টার্মিনাল টাইটনেস, ভোল্টেজ চেক এবং লোড টেস্ট অবশ্যই করতে হবে। এগুলোও খারাপ হয় এবং হঠাৎ করেই বসে যায়।","verdict":"ফ্রি মানেই চিন্তামুক্ত নয়।"},{"myth":"ব্যাটারি ফ্লোরে রাখলে চার্জ ডিসচার্জ হয়ে যায়।","reality":"এটি পুরনো দিনের রাবার কেস ব্যাটারির সমস্যা ছিল। আধুনিক প্লাস্টিক কেস ব্যাটারিতে এই সমস্যা নেই। তবে কাঠের র‍্যাক বা ইনসুলেটর ম্যাটের ওপর রাখা সেফটির জন্য ভালো।"}],"image_name":"/images/loader/batt98_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ব্যাটারি"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"সালফেশন (Sulfation)","content":"ব্যাটারি যদি দীর্ঘ দিন চার্জ ছাড়া বা কম চার্জে (Undercharged) থাকে, তবে প্লেটের ওপর লেড সালফেটের শক্ত ক্রিস্টাল জমে যায়। একে সালফেশন বলে। এটি ব্যাটারির ক্ষমতা পাকাপাকিভাবে নষ্ট করে দেয়। নিয়মিত ''ইকুয়ালাইজিং চার্জ'' (Equalizing Charge) দিলে এটি রোধ করা যায়।"},{"title":"C10 রেটিং","content":"ব্যাটারির গায়ে লেখা থাকে C10 বা C20। C10 মানে হলো ব্যাটারিটি তার পূর্ণ ক্ষমতা ১০ ঘণ্টায় ডিসচার্জ করতে পারবে। যদি দ্রুত ১ ঘণ্টায় ডিসচার্জ করেন, তবে তার ক্ষমতা অনেক কমে যাবে। সাবস্টেশনের ব্যাটারি সাধারণত C10 রেটিংয়ের হয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.8' AND language = 'bn';

-- Lesson 9.9
UPDATE training_chapters
SET
  content = '{"level_id":"9.9","badge_name":"যন্ত্রের স্বাস্থ্য পরীক্ষা (Testing Manual)","level_title":"ক্যাপাসিটর ব্যাংক টেস্টিং: পাওয়ার বুস্টারের কার্যকারিতা","mission_briefing":"বিদ্যুৎ বিলের জরিমানা (Power Factor Penalty) থেকে বাঁচতে এবং ভোল্টেজ ঠিক রাখতে সাবস্টেশনে ''ক্যাপাসিটর ব্যাংক'' ব্যবহার করা হয়। একে পাওয়ার সিস্টেমের ''বুস্টার ডোজ'' বলা যেতে পারে। কিন্তু ক্যাপাসিটর হলো এমন এক যন্ত্র যা অফ করার পরেও নিজের মধ্যে মারাত্মক চার্জ জমিয়ে রাখে। একে হ্যান্ডেল করা মানে ঘুমন্ত বাঘের সাথে খেলা করা। আজকের মিশনে আমরা শিখব কীভাবে নিরাপদে এই ব্যাংকের স্বাস্থ্য পরীক্ষা করা যায়।","sections":[{"title":"ক্যাপাসিটর ব্যাংক পরীক্ষার ধাপসমূহ","image_name":"/images/loader/cap99_bulge.webp","points":[{"item_name":"১. ভিজ্যুয়াল ইন্সপেকশন: ফুলে যাওয়া ক্যান","image_name":"/images/loader/cap99_bulge.webp","specifications":"প্রতিটি ক্যাপাসিটর ইউনিট বা ''ক্যান'' (Can) ভালো করে দেখা।","importance":"ক্যাপাসিটর নষ্ট হওয়ার প্রথম লক্ষণ হলো এটি ফুলে যায় (Bulging)। যেমন নষ্ট ব্যাটারি ফুলে ওঠে। যদি কোনো ইউনিট ফোলা থাকে বা তেল লিক করে, তবে সেটিকে অবিলম্বে বদলাতে হবে। এটি যেকোনো সময় ব্লাস্ট হতে পারে।","daily_check":"বুশিং এবং টার্মিনালে কোনো কালচে দাগ বা আর্কিং মার্ক আছে কিনা দেখুন।","image_caption":"ফোলা ক্যান · বদলান"},{"item_name":"২. ক্যাপাসিট্যান্স মেজারমেন্ট","image_name":"/images/loader/cap99_uf.webp","specifications":"বিশেষ ক্যাপাসিট্যান্স মিটার বা ভালো মানের এলসিআর (LCR) মিটার ব্যবহার করে মাইক্রো-ফ্যারাড (µF) মাপা হয়।","importance":"প্রতিটি ইউনিটের গায়ে তার রেটিং লেখা থাকে (যেমন: 200 µF)। মেপে দেখতে হবে ভ্যালুটি তার কাছাকাছি আছে কিনা। সাধারণত -৫% থেকে +১০% এর মধ্যে থাকলে ঠিক আছে। ভ্যালু কমে যাওয়া মানে ক্যাপাসিটর দুর্বল হয়ে গেছে, যা পাওয়ার ফ্যাক্টর ইম্প্রুভ করতে পারবে না।","daily_check":"পরিমাপের আগে ক্যাপাসিটরকে পুরোপুরি ডিসচার্জ এবং আইসোলেট করা বাধ্যতামূলক।","image_caption":"µF মাপুন"},{"item_name":"৩. ডিসচার্জ রেসিস্টর টেস্ট","image_name":"/images/loader/cap99_resist.webp","specifications":"মাল্টিমিটার দিয়ে ক্যাপাসিটরের দুই টার্মিনালের মধ্যে রেজিস্ট্যান্স মাপা।","importance":"প্রতিটি ক্যাপাসিটরের ভেতরে বা বাইরে একটি ডিসচার্জ রেসিস্টর থাকে, যা লাইন অফ হওয়ার পর ক্যাপাসিটরের চার্জ শুষে নেয়। এটি নষ্ট হয়ে গেলে ক্যাপাসিটর দিনের পর দিন চার্জ ধরে রাখবে, যা টেকনিশিয়ানের জন্য প্রাণঘাতী হতে পারে।","daily_check":"রেসিস্ট্যান্স ভ্যালু ম্যানুফ্যাকচারারের ডেটার সাথে মিলছে কিনা দেখুন।","image_caption":"ডিসচার্জ রেসিস্টর"},{"item_name":"৪. নিউট্রাল ডিসপ্লেসমেন্ট বা ব্যালেন্স চেক","image_name":"/images/loader/cap99_nct.webp","specifications":"ব্যাংক অন থাকা অবস্থায় ক্ল্যাম্প মিটার দিয়ে নিউট্রাল কারেন্ট মাপা (স্টার কানেকশনের জন্য)।","importance":"সুস্থ অবস্থায় তিন ফেজের ক্যাপাসিটর ব্যালেন্সড থাকে, তাই নিউট্রাল দিয়ে খুব কম কারেন্ট যায়। যদি নিউট্রাল কারেন্ট হঠাৎ বেড়ে যায়, তবে বুঝবেন কোনো এক ফেজের ক্যাপাসিটর ইউনিট ফিউজ হয়ে গেছে বা নষ্ট হয়ে গেছে।","daily_check":"NCT (Neutral Current Transformer) এর কানেকশন ঠিক আছে কিনা দেখুন।","image_caption":"নিউট্রাল · NCT"}],"image_caption":"ফোলা ক্যান · বদলান"}],"pro_tip":{"title":"ওস্তাদের পরামর্শ (Pro Tips)","content":["১. ১০ মিনিটের নিয়ম: ক্যাপাসিটর ব্যাংক অফ করার পর সাথে সাথে হাত দেবেন না বা আর্থ করবেন না। অন্তত ১০ মিনিট অপেক্ষা করুন যাতে ভেতরের ডিসচার্জ রেসিস্টর চার্জ কমিয়ে দিতে পারে।","২. ডিসচার্জ রড সবার আগে: ১০ মিনিট পর কাজ শুরুর আগে ডিসচার্জ রড দিয়ে প্রতিটি টার্মিনাল আর্থের সাথে শর্ট করুন। এবং কাজের সময় টার্মিনালগুলো তার দিয়ে শর্ট করে রাখুন।","৩. লুজ কানেকশন মানেই আগুন: ক্যাপাসিটর ব্যাংক প্রচুর কারেন্ট টানে। কানেকশন সামান্য লুজ থাকলে সেখানে ভয়ানক হিট তৈরি হয়। টর্ক রেঞ্চ দিয়ে সব নাট-বোল্ট টাইট দিন।","৪. ভেন্টিলেশন: ক্যাপাসিটর রুমে যেন পর্যাপ্ত বাতাস চলাচলের ব্যবস্থা থাকে। অতিরিক্ত গরমে ক্যাপাসিটরের আয়ু কমে যায়।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"সুইচ অফ করেছি, এখন তো সেফ, হাত দেওয়া যাবে।","reality":"জীবনের সবচেয়ে বড় ভুল! অফ করার পরেও ক্যাপাসিটর পূর্ণ ভোল্টেজে চার্জ ধরে রাখতে পারে। ডিসচার্জ না করা পর্যন্ত এটি একটি ''লোডেড গান'' (Loaded Gun)।","verdict":"ডিসচার্জ ছাড়া স্পর্শ নিষেধ।"},{"myth":"ফিউজ ভালো আছে মানে ক্যাপাসিটর ভালো আছে।","reality":"না। অনেক সময় ক্যাপাসিটরের ভেতরের এলিমেন্ট নষ্ট হয়ে ওপেন হয়ে যায়, কিন্তু ফিউজ কাটে না। ক্যাপাসিট্যান্স মিটার দিয়ে মাপাই আসল পরীক্ষা।"}],"image_name":"/images/loader/cap99_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ক্যাপাসিটর"},"advanced_section":{"title":"ইঞ্জিনিয়ারিং ইনসাইট (Engineering Insights)","facts":[{"title":"হারমোনিক্স (Harmonics)","content":"পাওয়ার সিস্টেমে হারমোনিক্স (বিকৃত ওয়েভফর্ম) থাকলে ক্যাপাসিটর ব্যাংক তার প্রতি খুব সেনসিটিভ হয়। ক্যাপাসিটর হারমোনিক্সকে বাড়িয়ে দিতে পারে, যার ফলে ক্যাপাসিটর অতিরিক্ত গরম হয় বা ব্লাস্ট করে। এর সমাধানের জন্য ক্যাপাসিটরের সাথে ''সিরিজ রিঅ্যাক্টর'' (Series Reactor) ব্যবহার করা হয়, একে ডি-টিউনড (Detuned) ব্যাংক বলে।"},{"title":"kVAr এবং Power Factor","content":"আমরা ক্যাপাসিটর মাপি µF-এ কিন্তু ব্যাংকের রেটিং হয় kVAr-এ। সূত্র হলো: kVAr = 2πfCV² × 10⁻⁹। অর্থাৎ ভোল্টেজ যদি ১০% কমে যায়, তবে ক্যাপাসিটর ব্যাংকের পাওয়ার ডেলিভারি (kVAr) প্রায় ১৯% কমে যাবে। তাই ভোল্টেজ ঠিক রাখা জরুরি।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '9.9' AND language = 'bn';

